.button {
  background: #2563eb;
  color: white;
  padding: 0.5rem 1rem;
  border-radius: 0.375rem;
}

.button:hover { background: #1d4ed8; }

.primary { composes: button; font-weight: 600; }

import styles from './Button.module.css';

type Props = React.ButtonHTMLAttributes<HTMLButtonElement> & { primary?: boolean };

export function Button({ primary, className, ...rest }: Props) {
  return (
    <button
      className={[styles.button, primary && styles.primary, className].filter(Boolean).join(' ')}
      {...rest}
    />
  );
}

/* global.css */
:global(.no-scroll) { overflow: hidden; }

